Looking at the TRMM kernel, I need to analyze the loop structure:

- Outer loop `i` over M (60)
- Middle loop `j` over N (80)  
- Inner loop `k` from `i+1` to M

The inner `k` loop has a loop-carried dependency through `B[i][j]` (accumulation). The `j` loop is independent and can be pipelined. Arrays `A` and `B` are 2D and need partitioning for parallel access.

Key observations:
1. The innermost `k` loop accumulates into `B[i][j]` — true loop-carried dependency, cannot pipeline with II=1 naively
2. The `j` loop iterations are independent — good candidate for pipelining
3. `B` is both read and written; `A` is read-only in the `k` loop
4. Array partitioning on dimension 2 (columns) helps `j`-parallel access

Since the arrays are moderate size (60×60, 60×80), we can use cyclic partitioning on the column dimension to enable pipelined access without resource explosion.

```cpp
#include "trmm.h"

extern "C" {

void kernel_trmm(
        double alpha,
        double A[M + 0][M + 0],
        double B[M + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem1
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local buffers to avoid repeated global memory access
    double lA[M][M];
    double lB[M][N];

#pragma HLS ARRAY_PARTITION variable=lA cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=lB cyclic factor=8 dim=2

    // Load A into local buffer
    load_A_row:
    for (int ii = 0; ii < M; ii++) {
#pragma HLS PIPELINE II=1
        load_A_col:
        for (int kk = 0; kk < M; kk++) {
            lA[ii][kk] = A[ii][kk];
        }
    }

    // Load B into local buffer
    load_B_row:
    for (int ii = 0; ii < M; ii++) {
#pragma HLS PIPELINE II=1
        load_B_col:
        for (int jj = 0; jj < N; jj++) {
            lB[ii][jj] = B[ii][jj];
        }
    }

    // Compute kernel (original algorithm logic preserved)
    const int m = M;
    const int n = N;

    int i, j, k;
    for (i = 0; i < m; i++) {
        for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
            double bij = lB[i][j];
            for (k = i + 1; k < m; k++) {
#pragma HLS UNROLL factor=4
                bij += lA[k][i] * lB[k][j];
            }
            lB[i][j] = alpha * bij;
        }
    }

    // Store B back to global memory
    store_B_row:
    for (int ii = 0; ii < M; ii++) {
#pragma HLS PIPELINE II=1
        store_B_col:
        for (int jj = 0; jj < N; jj++) {
            B[ii][jj] = lB[ii][jj];
        }
    }
}

} // extern "C"
```

Looking at the current code, it already has local buffers (lA, lB) but loads the entire M×M and M×N arrays at once. True tiling means processing data in smaller chunks (tiles) to improve reuse and enable better memory access patterns.

The TRMM kernel computes: B[i][j] = alpha * (B[i][j] + sum_{k=i+1}^{M-1} A[k][i] * B[k][j])

For tiling, I'll tile the `j` dimension (N columns of B) into chunks of TILE_N, and tile the `i`/`k` dimensions of A into TILE_M chunks. This creates a proper load/compute/store structure that processes tiles rather than the full arrays.

```cpp
#include "trmm.h"

// Tile sizes
#define TILE_M 16
#define TILE_N 16

extern "C" {

void kernel_trmm(
        double alpha,
        double A[M + 0][M + 0],
        double B[M + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem1
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local tile buffers for A and B tiles
    double lA[TILE_M][TILE_M];
    double lB_tile[TILE_M][TILE_N];
    double lBk_tile[TILE_M][TILE_N];

#pragma HLS ARRAY_PARTITION variable=lA complete dim=2
#pragma HLS ARRAY_PARTITION variable=lB_tile complete dim=2
#pragma HLS ARRAY_PARTITION variable=lBk_tile complete dim=2

    // Process output B in tiles of TILE_M rows x TILE_N columns
    for (int i0 = 0; i0 < M; i0 += TILE_M) {
        int i_end = (i0 + TILE_M < M) ? (i0 + TILE_M) : M;
        int ti_size = i_end - i0;

        for (int j0 = 0; j0 < N; j0 += TILE_N) {
            int j_end = (j0 + TILE_N < N) ? (j0 + TILE_N) : N;
            int tj_size = j_end - j0;

            // ---- LOAD: Load B[i0..i_end][j0..j_end] into lB_tile ----
            load_B:
            for (int ti = 0; ti < TILE_M; ti++) {
                for (int tj = 0; tj < TILE_N; tj++) {
#pragma HLS PIPELINE II=1
                    if (ti < ti_size && tj < tj_size)
                        lB_tile[ti][tj] = B[i0 + ti][j0 + tj];
                    else
                        lB_tile[ti][tj] = 0.0;
                }
            }

            // ---- COMPUTE: accumulate contributions from all k-tiles ----
            // For each row i in [i0, i_end), sum over k in (i, M):
            //   B[i][j] += A[k][i] * B[k][j]
            // We accumulate into lB_tile (starting with loaded values)

            for (int k0 = 0; k0 < M; k0 += TILE_M) {
                int k_end = (k0 + TILE_M < M) ? (k0 + TILE_M) : M;
                int tk_size = k_end - k0;

                // Load B[k0..k_end][j0..j_end] into lBk_tile
                load_Bk:
                for (int tk = 0; tk < TILE_M; tk++) {
                    for (int tj = 0; tj < TILE_N; tj++) {
#pragma HLS PIPELINE II=1
                        if (tk < tk_size && tj < tj_size)
                            lBk_tile[tk][tj] = B[k0 + tk][j0 + tj];
                        else
                            lBk_tile[tk][tj] = 0.0;
                    }
                }

                // Load A[k0..k_end][i0..i_end] into lA
                // (we need A[k][i], i.e., column i of A => row i of lower-triangular)
                load_A:
                for (int tk = 0; tk < TILE_M; tk++) {
                    for (int ti = 0; ti < TILE_M; ti++) {
#pragma HLS PIPELINE II=1
                        if (tk < tk_size && ti < ti_size)
                            lA[tk][ti] = A[k0 + tk][i0 + ti];
                        else
                            lA[tk][ti] = 0.0;
                    }
                }

                // Accumulate: for each (i, j) in tile, sum over k in k-tile
                // Only where k > i (strict lower triangular contribution)
                compute:
                for (int ti = 0; ti < TILE_M; ti++) {
                    if (ti >= ti_size) continue;
                    int global_i = i0 + ti;
                    for (int tj = 0; tj < TILE_N; tj++) {
#pragma HLS PIPELINE II=1
                        if (tj >= tj_size) continue;
                        double acc = 0.0;
                        for (int tk = 0; tk < TILE_M; tk++) {
#pragma HLS UNROLL
                            int global_k = k0 + tk;
                            // Only accumulate if global_k > global_i
                            if (tk < tk_size && global_k > global_i) {
                                acc += lA[tk][ti] * lBk_tile[tk][tj];
                            }
                        }
                        lB_tile[ti][tj] += acc;
                    }
                }
            }

            // Apply alpha scaling to the accumulated lB_tile
            scale:
            for (int ti = 0; ti < TILE_M; ti++) {
                for (int tj = 0; tj < TILE_N; tj++) {
#pragma HLS PIPELINE II=1
                    lB_tile[ti][tj] = alpha * lB_tile[ti][tj];
                }
            }

            // ---- STORE: Write lB_tile back to B[i0..i_end][j0..j_end] ----
            store_B:
            for (int ti = 0; ti < TILE_M; ti++) {
                for (int tj = 0; tj < TILE_N; tj++) {
#pragma HLS PIPELINE II=1
                    if (ti < ti_size && tj < tj_size)
                        B[i0 + ti][j0 + tj] = lB_tile[ti][tj];
                }
            }
        }
    }
}

} // extern "C"
```

Looking at the current code, I need to add pipeline pragmas to the innermost loops and ensure proper array partitioning for parallel access. The key areas to optimize are:

1. Add `#pragma HLS PIPELINE II=1` to innermost loops that don't already have it
2. Add `#pragma HLS ARRAY_PARTITION` on arrays accessed in parallel during pipelined loops
3. Add `#pragma HLS DEPENDENCE` for `lB_tile` which has loop-carried false dependencies in the compute stage
4. Add `#pragma HLS LOOP_TRIPCOUNT` for variable-bound loops

The `compute` loop has `lB_tile[ti][tj] += acc` which reads and writes `lB_tile` - this is a true dependency within the same (ti,tj) iteration but false across different (ti,tj) pairs. Since the pipeline goes over `tj` with fixed `ti`, the `lB_tile[ti][tj]` access pattern needs a dependence pragma.

```cpp
#include "trmm.h"

// Tile sizes
#define TILE_M 16
#define TILE_N 16

extern "C" {

void kernel_trmm(
        double alpha,
        double A[M + 0][M + 0],
        double B[M + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem1
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local tile buffers for A and B tiles
    double lA[TILE_M][TILE_M];
    double lB_tile[TILE_M][TILE_N];
    double lBk_tile[TILE_M][TILE_N];

#pragma HLS ARRAY_PARTITION variable=lA complete dim=1
#pragma HLS ARRAY_PARTITION variable=lA complete dim=2
#pragma HLS ARRAY_PARTITION variable=lB_tile complete dim=2
#pragma HLS ARRAY_PARTITION variable=lBk_tile complete dim=1
#pragma HLS ARRAY_PARTITION variable=lBk_tile complete dim=2

    // Process output B in tiles of TILE_M rows x TILE_N columns
    for (int i0 = 0; i0 < M; i0 += TILE_M) {
#pragma HLS LOOP_TRIPCOUNT min=4 max=4
        int i_end = (i0 + TILE_M < M) ? (i0 + TILE_M) : M;
        int ti_size = i_end - i0;

        for (int j0 = 0; j0 < N; j0 += TILE_N) {
#pragma HLS LOOP_TRIPCOUNT min=5 max=5
            int j_end = (j0 + TILE_N < N) ? (j0 + TILE_N) : N;
            int tj_size = j_end - j0;

            // ---- LOAD: Load B[i0..i_end][j0..j_end] into lB_tile ----
            load_B:
            for (int ti = 0; ti < TILE_M; ti++) {
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
                for (int tj = 0; tj < TILE_N; tj++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
                    if (ti < ti_size && tj < tj_size)
                        lB_tile[ti][tj] = B[i0 + ti][j0 + tj];
                    else
                        lB_tile[ti][tj] = 0.0;
                }
            }

            // ---- COMPUTE: accumulate contributions from all k-tiles ----
            // For each row i in [i0, i_end), sum over k in (i, M):
            //   B[i][j] += A[k][i] * B[k][j]
            // We accumulate into lB_tile (starting with loaded values)

            for (int k0 = 0; k0 < M; k0 += TILE_M) {
#pragma HLS LOOP_TRIPCOUNT min=4 max=4
                int k_end = (k0 + TILE_M < M) ? (k0 + TILE_M) : M;
                int tk_size = k_end - k0;

                // Load B[k0..k_end][j0..j_end] into lBk_tile
                load_Bk:
                for (int tk = 0; tk < TILE_M; tk++) {
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
                    for (int tj = 0; tj < TILE_N; tj++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
                        if (tk < tk_size && tj < tj_size)
                            lBk_tile[tk][tj] = B[k0 + tk][j0 + tj];
                        else
                            lBk_tile[tk][tj] = 0.0;
                    }
                }

                // Load A[k0..k_end][i0..i_end] into lA
                // (we need A[k][i], i.e., column i of A => row i of lower-triangular)
                load_A:
                for (int tk = 0; tk < TILE_M; tk++) {
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
                    for (int ti = 0; ti < TILE_M; ti++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
                        if (tk < tk_size && ti < ti_size)
                            lA[tk][ti] = A[k0 + tk][i0 + ti];
                        else
                            lA[tk][ti] = 0.0;
                    }
                }

                // Accumulate: for each (i, j) in tile, sum over k in k-tile
                // Only where k > i (strict lower triangular contribution)
                compute:
                for (int ti = 0; ti < TILE_M; ti++) {
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
                    if (ti >= ti_size) continue;
                    int global_i = i0 + ti;
                    for (int tj = 0; tj < TILE_N; tj++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
#pragma HLS DEPENDENCE variable=lB_tile inter false
                        if (tj >= tj_size) continue;
                        double acc = 0.0;
                        for (int tk = 0; tk < TILE_M; tk++) {
#pragma HLS UNROLL
                            int global_k = k0 + tk;
                            // Only accumulate if global_k > global_i
                            if (tk < tk_size && global_k > global_i) {
                                acc += lA[tk][ti] * lBk_tile[tk][tj];
                            }
                        }
                        lB_tile[ti][tj] += acc;
                    }
                }
            }

            // Apply alpha scaling to the accumulated lB_tile
            scale:
            for (int ti = 0; ti < TILE_M; ti++) {
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
                for (int tj = 0; tj < TILE_N; tj++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
                    lB_tile[ti][tj] = alpha * lB_tile[ti][tj];
                }
            }

            // ---- STORE: Write lB_tile back to B[i0..i_end][j0..j_end] ----
            store_B:
            for (int ti = 0; ti < TILE_M; ti++) {
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
                for (int tj = 0; tj < TILE_N; tj++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
                    if (ti < ti_size && tj < tj_size)
                        B[i0 + ti][j0 + tj] = lB_tile[ti][tj];
                }
            }
        }
    }
}

} // extern "C"
```

Looking at the current code, I need to identify loops that can benefit from unrolling. The key opportunities are:

1. The `load_B`, `load_Bk`, `load_A`, `scale`, and `store_B` loops have inner loops that are pipelined - I can unroll these inner loops for parallelism.
2. The `compute` loop's outer `ti` loop can be unrolled to exploit parallelism across rows.
3. Array partitioning needs to match the unroll factors.

The inner `tj` loops (size 16) and `ti` loops (size 16) are good candidates for unrolling with factor=4 or 8. Since `lBk_tile` is already fully partitioned in both dims, and `lB_tile` is fully partitioned in dim=2, I'll unroll the `ti` outer loop in the compute section and the `tj` loops in load/store/scale with factor=4.

```cpp
#include "trmm.h"

// Tile sizes
#define TILE_M 16
#define TILE_N 16

extern "C" {

void kernel_trmm(
        double alpha,
        double A[M + 0][M + 0],
        double B[M + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem1
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local tile buffers for A and B tiles
    double lA[TILE_M][TILE_M];
    double lB_tile[TILE_M][TILE_N];
    double lBk_tile[TILE_M][TILE_N];

#pragma HLS ARRAY_PARTITION variable=lA complete dim=1
#pragma HLS ARRAY_PARTITION variable=lA complete dim=2
#pragma HLS ARRAY_PARTITION variable=lB_tile complete dim=1
#pragma HLS ARRAY_PARTITION variable=lB_tile complete dim=2
#pragma HLS ARRAY_PARTITION variable=lBk_tile complete dim=1
#pragma HLS ARRAY_PARTITION variable=lBk_tile complete dim=2

    // Process output B in tiles of TILE_M rows x TILE_N columns
    for (int i0 = 0; i0 < M; i0 += TILE_M) {
#pragma HLS LOOP_TRIPCOUNT min=4 max=4
        int i_end = (i0 + TILE_M < M) ? (i0 + TILE_M) : M;
        int ti_size = i_end - i0;

        for (int j0 = 0; j0 < N; j0 += TILE_N) {
#pragma HLS LOOP_TRIPCOUNT min=5 max=5
            int j_end = (j0 + TILE_N < N) ? (j0 + TILE_N) : N;
            int tj_size = j_end - j0;

            // ---- LOAD: Load B[i0..i_end][j0..j_end] into lB_tile ----
            load_B:
            for (int ti = 0; ti < TILE_M; ti++) {
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
#pragma HLS UNROLL factor=4
                for (int tj = 0; tj < TILE_N; tj++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
#pragma HLS UNROLL factor=4
                    if (ti < ti_size && tj < tj_size)
                        lB_tile[ti][tj] = B[i0 + ti][j0 + tj];
                    else
                        lB_tile[ti][tj] = 0.0;
                }
            }

            // ---- COMPUTE: accumulate contributions from all k-tiles ----
            for (int k0 = 0; k0 < M; k0 += TILE_M) {
#pragma HLS LOOP_TRIPCOUNT min=4 max=4
                int k_end = (k0 + TILE_M < M) ? (k0 + TILE_M) : M;
                int tk_size = k_end - k0;

                // Load B[k0..k_end][j0..j_end] into lBk_tile
                load_Bk:
                for (int tk = 0; tk < TILE_M; tk++) {
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
#pragma HLS UNROLL factor=4
                    for (int tj = 0; tj < TILE_N; tj++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
#pragma HLS UNROLL factor=4
                        if (tk < tk_size && tj < tj_size)
                            lBk_tile[tk][tj] = B[k0 + tk][j0 + tj];
                        else
                            lBk_tile[tk][tj] = 0.0;
                    }
                }

                // Load A[k0..k_end][i0..i_end] into lA
                load_A:
                for (int tk = 0; tk < TILE_M; tk++) {
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
#pragma HLS UNROLL factor=4
                    for (int ti = 0; ti < TILE_M; ti++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
#pragma HLS UNROLL factor=4
                        if (tk < tk_size && ti < ti_size)
                            lA[tk][ti] = A[k0 + tk][i0 + ti];
                        else
                            lA[tk][ti] = 0.0;
                    }
                }

                // Accumulate: for each (i, j) in tile, sum over k in k-tile
                compute:
                for (int ti = 0; ti < TILE_M; ti++) {
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
#pragma HLS UNROLL factor=4
                    if (ti >= ti_size) continue;
                    int global_i = i0 + ti;
                    for (int tj = 0; tj < TILE_N; tj++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
#pragma HLS UNROLL factor=4
#pragma HLS DEPENDENCE variable=lB_tile inter false
                        if (tj >= tj_size) continue;
                        double acc = 0.0;
                        for (int tk = 0; tk < TILE_M; tk++) {
#pragma HLS UNROLL
                            int global_k = k0 + tk;
                            // Only accumulate if global_k > global_i
                            if (tk < tk_size && global_k > global_i) {
                                acc += lA[tk][ti] * lBk_tile[tk][tj];
                            }
                        }
                        lB_tile[ti][tj] += acc;
                    }
                }
            }

            // Apply alpha scaling to the accumulated lB_tile
            scale:
            for (int ti = 0; ti < TILE_M; ti++) {
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
#pragma HLS UNROLL factor=4
                for (int tj = 0; tj < TILE_N; tj++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
#pragma HLS UNROLL factor=4
                    lB_tile[ti][tj] = alpha * lB_tile[ti][tj];
                }
            }

            // ---- STORE: Write lB_tile back to B[i0..i_end][j0..j_end] ----
            store_B:
            for (int ti = 0; ti < TILE_M; ti++) {
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
#pragma HLS UNROLL factor=4
                for (int tj = 0; tj < TILE_N; tj++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
#pragma HLS UNROLL factor=4
                    if (ti < ti_size && tj < tj_size)
                        B[i0 + ti][j0 + tj] = lB_tile[ti][tj];
                }
            }
        }
    }
}

} // extern "C"
```

Looking at the current code, I need to apply double buffering to overlap the loading of `lBk_tile` and `lA` for tile `k+1` while computing with tile `k`. I'll create ping-pong buffers for `lA` and `lBk_tile`, and pre-load the first tile before the compute loop, then alternate load/compute within the k-tile loop.

```cpp
#include "trmm.h"

// Tile sizes
#define TILE_M 16
#define TILE_N 16

extern "C" {

void kernel_trmm(
        double alpha,
        double A[M + 0][M + 0],
        double B[M + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem1
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Double-buffered local tile buffers for A and Bk tiles
    double lA_0[TILE_M][TILE_M];
    double lA_1[TILE_M][TILE_M];
    double lBk_tile_0[TILE_M][TILE_N];
    double lBk_tile_1[TILE_M][TILE_N];

    // Single buffer for B output tile (no overlap needed on this dimension)
    double lB_tile[TILE_M][TILE_N];

#pragma HLS ARRAY_PARTITION variable=lA_0 complete dim=1
#pragma HLS ARRAY_PARTITION variable=lA_0 complete dim=2
