typedef ap_uint<512> wide_bus_t;

// Helper: read a row of doubles from wide bus memory into a local array
// src: wide bus pointer, byte_offset: byte offset into src, dst: local double array, count: number of doubles
static void wide_bus_read_row(double* dst, const wide_bus_t* src, int double_offset, int count) {
#pragma HLS INLINE
    int word_start = double_offset / DOUBLES_PER_WORD;
    int elem_start = double_offset % DOUBLES_PER_WORD;

    int idx = 0;
    read_loop:
    for (int w = word_start; idx < count; w++) {
#pragma HLS PIPELINE II=1
        wide_bus_t word = src[w];
        for (int e = (w == word_start ? elem_start : 0); e < DOUBLES_PER_WORD && idx < count; e++) {
#pragma HLS UNROLL
            ap_uint<64> bits = word.range(e*64+63, e*64);
            double val;
            // reinterpret bits as double
            union { unsigned long long u; double d; } cvt;
            cvt.u = (unsigned long long)bits;
            dst[idx++] = cvt.d;
        }
    }
}

// Helper: write a row of doubles to wide bus memory from a local array
static void wide_bus_write_row(wide_bus_t* dst, const double* src, int double_offset, int count) {
#pragma HLS INLINE
    int word_start = double_offset / DOUBLES_PER_WORD;
    int elem_start = double_offset % DOUBLES_PER_WORD;

    int idx = 0;
    write_loop:
    for (int w = word_start; idx < count; w++) {
#pragma HLS PIPELINE II=1
        wide_bus_t word = dst[w];
        for (int e = (w == word_start ? elem_start : 0); e < DOUBLES_PER_WORD && idx < count; e++) {
#pragma HLS UNROLL
            union { unsigned long long u; double d; } cvt;
            cvt.d = src[idx++];
            word.range(e*64+63, e*64) = cvt.u;
        }
        dst[w] = word;
    }
}

extern "C" {

void kernel_trmm(
        double alpha,
        wide_bus_t* A,
        wide_bus_t* B)
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0 max_read_burst_length=256 max_write_burst_length=256
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem1 max_read_burst_length=256 max_write_burst_length=256
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Double-buffered local tile buffers for A and Bk tiles
    double lA_0[TILE_M][TILE_M];
    double lA_1[TILE_M][TILE_M];
    double lBk_tile_0[TILE_M][TILE_N];
    double lBk_tile_1[TILE_M][TILE_N];

    // Single buffer for B output tile
    double lB_tile[TILE_M][TILE_N];

#pragma HLS ARRAY_PARTITION variable=lA_0 cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=lA_0 complete dim=1
#pragma HLS ARRAY_PARTITION variable=lA_1 cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=lA_1 complete dim=1
#pragma HLS ARRAY_PARTITION variable=lBk_tile_0 cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=lBk_tile_0 complete dim=1
#pragma HLS ARRAY_PARTITION variable=lBk_tile_1 cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=lBk_tile_1 complete dim=1
#pragma HLS ARRAY_PARTITION variable=lB_tile cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=lB_tile complete dim=1

    // Process output B in tiles of TILE_M rows x TILE_N columns
    for (int i0 = 0; i0 < M; i0 += TILE_M) {
#pragma HLS LOOP_TRIPCOUNT min=4 max=4
        int i_end = (i0 + TILE_M < M) ? (i0 + TILE_M) : M;
        int ti_size = i_end - i0;

        for (int j0 = 0; j0 < N; j0 += TILE_N) {
#pragma HLS LOOP_TRIPCOUNT min=5 max=5
            int j_end = (j0 + TILE_N < N) ? (j0 + TILE_N) : N;
            int tj_size = j_end - j0;

            // ---- LOAD: Load B[i0..i_end][j0..j_end] into lB_tile ----
            load_B:
            for (int ti = 0; ti < TILE_M; ti++) {
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
                if (ti < ti_size) {
                    wide_bus_read_row(lB_tile[ti], B, (i0 + ti) * N + j0, tj_size);
                    for (int tj = tj_size; tj < TILE_N; tj++) {
#pragma HLS PIPELINE II=1
                        lB_tile[ti][tj] = 0.0;
                    }
                } else {
                    for (int tj = 0; tj < TILE_N; tj++) {
#pragma HLS PIPELINE II=1
                        lB_tile[ti][tj] = 0.0;
                    }
                }
            }

            // ---- PRE-LOAD: Load first k-tile (k0=0) into buffer set 0 ----
            {
                int k0_pre = 0;
                int k_end_pre = (k0_pre + TILE_M < M) ? (k0_pre + TILE_M) : M;
                int tk_size_pre = k_end_pre - k0_pre;

                // Pre-load lBk_tile_0 for k0=0
                preload_Bk:
                for (int tk = 0; tk < TILE_M; tk++) {
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
                    if (tk < tk_size_pre) {
                        wide_bus_read_row(lBk_tile_0[tk], B, (k0_pre + tk) * N + j0, tj_size);
                        for (int tj = tj_size; tj < TILE_N; tj++) {
#pragma HLS PIPELINE II=1
                            lBk_tile_0[tk][tj] = 0.0;
                        }
                    } else {
                        for (int tj = 0; tj < TILE_N; tj++) {
#pragma HLS PIPELINE II=1
                            lBk_tile_0[tk][tj] = 0.0;
                        }
                    }
                }

                // Pre-load lA_0 for k0=0
                preload_A:
                for (int tk = 0; tk < TILE_M; tk++) {
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
                    if (tk < tk_size_pre) {
                        wide_bus_read_row(lA_0[tk], A, (k0_pre + tk) * M + i0, ti_size);
                        for (int ti = ti_size; ti < TILE_M; ti++) {
#pragma HLS PIPELINE II=1
                            lA_0[tk][ti] = 0.0;
                        }
                    } else {
                        for (int ti = 0; ti < TILE_M; ti++) {
#pragma HLS PIPELINE II=1
                            lA_0[tk][ti] = 0.0;
                        }
                    }
                }
            }

            // ---- COMPUTE: accumulate contributions from all k-tiles ----
            for (int k0 = 0; k0 < M; k0 += TILE_M) {
#pragma HLS LOOP_TRIPCOUNT min=4 max=4
                int k_end   = (k0 + TILE_M < M) ? (k0 + TILE_M) : M;
                int tk_size = k_end - k0;

                int buf = (k0 / TILE_M) % 2;

                // ---- LOAD NEXT k-tile into the OTHER buffer (ping-pong) ----
                int k0_next = k0 + TILE_M;
                if (k0_next < M) {
                    int k_end_next  = (k0_next + TILE_M < M) ? (k0_next + TILE_M) : M;
                    int tk_size_next = k_end_next - k0_next;

                    if (buf == 0) {
                        // Load into buffer_1 while we compute from buffer_0
                        load_Bk_next_1:
                        for (int tk = 0; tk < TILE_M; tk++) {
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
                            if (tk < tk_size_next) {
                                wide_bus_read_row(lBk_tile_1[tk], B, (k0_next + tk) * N + j0, tj_size);
                                for (int tj = tj_size; tj < TILE_N; tj++) {
#pragma HLS PIPELINE II=1
                                    lBk_tile_1[tk][tj] = 0.0;
                                }
                            } else {
                                for (int tj = 0; tj < TILE_N; tj++) {
#pragma HLS PIPELINE II=1
                                    lBk_tile_1[tk][tj] = 0.0;
                                }
                            }
                        }
                        load_A_next_1:
                        for (int tk = 0; tk < TILE_M; tk++) {
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
                            if (tk < tk_size_next) {
                                wide_bus_read_row(lA_1[tk], A, (k0_next + tk) * M + i0, ti_size);
                                for (int ti = ti_size; ti < TILE_M; ti++) {
#pragma HLS PIPELINE II=1
                                    lA_1[tk][ti] = 0.0;
                                }
                            } else {
                                for (int ti = 0; ti < TILE_M; ti++) {
#pragma HLS PIPELINE II=1
                                    lA_1[tk][ti] = 0.0;
                                }
                            }
                        }
                    } else {
                        // Load into buffer_0 while we compute from buffer_1
                        load_Bk_next_0:
                        for (int tk = 0; tk < TILE_M; tk++) {
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
                            if (tk < tk_size_next) {
                                wide_bus_read_row(lBk_tile_0[tk], B, (k0_next + tk) * N + j0, tj_size);
                                for (int tj = tj_size; tj < TILE_N; tj++) {
#pragma HLS PIPELINE II=1
                                    lBk_tile_0[tk][tj] = 0.0;
                                }
                            } else {
                                for (int tj = 0; tj < TILE_N; tj++) {
#pragma HLS PIPELINE II=1
                                    lBk_tile_0[tk][tj] = 0.0;
                                }
                            }
                        }
                        load_A_next_0:
                        for (int tk = 0; tk < TILE_M; tk++) {
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
                            if (tk < tk_size_next) {
                                wide_bus_read_row(lA_0[tk], A, (k0_next + tk) * M + i0, ti_size);
                                for (int ti = ti_size; ti < TILE_M; ti++) {
#pragma HLS PIPELINE II=1
                                    lA_0[tk][ti] = 0.0;
                                }
                            } else {
                                for (int ti = 0; ti < TILE_M; ti++) {
#pragma HLS PIPELINE II=1
                                    lA_0[tk][ti] = 0.0;
                                }
                            }
                        }
                    }
                }

                // ---- COMPUTE from the current buffer (buf selects which) ----
                if (buf == 0) {
                    compute_0:
                    for (int ti = 0; ti < TILE_M; ti++) {
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
#pragma HLS UNROLL factor=4
                        if (ti >= ti_size) continue;
                        int global_i = i0 + ti;
                        for (int tj = 0; tj < TILE_N; tj++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
#pragma HLS UNROLL factor=4
#pragma HLS DEPENDENCE variable=lB_tile inter false
                            if (tj >= tj_size) continue;
                            double acc = 0.0;
                            for (int tk = 0; tk < TILE_M; tk++) {
#pragma HLS UNROLL
                                int global_k = k0 + tk;
                                if (tk < tk_size && global_k > global_i) {
                                    acc += lA_0[tk][ti] * lBk_tile_0[tk][tj];
                                }
                            }
                            lB_tile[ti][tj] += acc;
                        }
                    }
                } else {
                    compute_1:
                    for (int ti = 0; ti < TILE_M; ti++) {
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
#pragma HLS UNROLL factor=4
                        if (ti >= ti_size) continue;
                        int global_i = i0 + ti;
                        for (int tj = 0; tj < TILE_N; tj++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
#pragma HLS UNROLL factor=4
#pragma HLS DEPENDENCE variable=lB_tile inter false
                            if (tj >= tj_size) continue;
                            double acc = 0.0;
                            for (int tk = 0; tk < TILE_M; tk++) {
#pragma HLS UNROLL
                                int global_k = k0 + tk;
                                if (tk < tk_size && global_k > global_i) {
                                    acc += lA_1[tk][ti] * lBk_tile_1[tk][tj];
                                }
                            }
                            lB_tile[ti][tj] += acc;
                        }
                    }
                }
            } // end k0 loop

            // Apply alpha scaling to the accumulated lB_tile
            scale:
            for (int ti = 0; ti < TILE_M; ti++) {
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
#pragma HLS UNROLL factor=4
                for (int tj = 0; tj < TILE_N; tj++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
#pragma HLS UNROLL factor=4
                    lB_tile[ti][tj] = alpha * lB_tile[ti][tj];
                }
            }

            // ---- STORE: Write lB_tile back to B[i0..i_end][j0..j_end] ----
            store_B:
            for (int ti = 0; ti < TILE_M; ti++) {
#pragma HLS LOOP_TRIPCOUNT min=16 max=16
                if (ti < ti_size) {
                    wide_bus_write_row(B, lB_tile[ti], (i0 + ti) * N + j0, tj_size);
                }
            }
        }
    }
}

